import {createSelector} from 'reselect'

import {getFavoriteAgentPoolsHref} from '../../../../../routes'
import {getFavoriteAgentTree} from '../../AgentsPages.selectors'
import {AgentTreeItemType} from '../AgentsSidebar.types'

export const getFavoriteAgentsPoolsLink = createSelector(
  [getFavoriteAgentTree],
  favoritePools =>
    ({
      id: 'favorite-agents-link',
      key: 'favorite-agents-link-overview',
      type: AgentTreeItemType.FAVORITE_LINK,
      title: 'Overview',
      level: 0,
      to: getFavoriteAgentPoolsHref(),
      active: false,
      focusable: true,
      disconnectedCount: favoritePools.reduce((acc, pool) => acc + pool.disconnectedCount, 0),
    }) as const,
)
