import {createSelector} from 'reselect'

import {AgentTreeItemCategory} from '../../AgentsSidebar.types'
import {makeFlatAgentsTree} from '../../utils/makeFlatAgentsTree'
import {getExpandState, getIsSearching} from '../getExpand'

import {getPipelinesMatchingAgentsTree} from './pipelinesMatchingTree'

export const getPipelinesFlatAgentsTree = createSelector(
  [
    getPipelinesMatchingAgentsTree,
    getExpandState,
    getIsSearching,
    () => AgentTreeItemCategory.MAIN,
  ],
  makeFlatAgentsTree,
)
