import AddIcon from '@jetbrains/icons/add.svg'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import type {ListDataItem} from '@jetbrains/ring-ui-built/components/list/list'
import PopupMenu from '@jetbrains/ring-ui-built/components/popup-menu/popup-menu'
import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import classNames from 'classnames'
import * as React from 'react'
import {useCallback} from 'react'

import {usePermission} from '../../../../../hooks/usePermission'
import {Permission, ROOT_PROJECT_ID} from '../../../../../types'
import {resolveHelpURL} from '../../../../../utils/url'
import AgentAuthDialog from '../../../../common/AgentAuthDialog/AgentAuthDialog'
import {useAuthAgentDialog} from '../../../../common/AgentAuthDialog/AgentAuthDialog.hooks'
import HelpLink from '../../../../common/HelpLink/HelpLink'
import {addAgentPoolHint} from '../../../../packages/Hints/HintItems/Hints.agents'
import {useHint} from '../../../../packages/Hints/Hints.hooks'
import {
  dockerAgentImageUrl,
  fullDistributions,
  fullZipFileDistribution,
  isFullDistributions,
  windowsInstallerUrl,
  zipFileDistribution,
} from '../../components/InstallAgent/InstallAgent.consts'

import CreateAgentPoolPopup from './CreateAgentPoolPopup/CreateAgentPoolPopup'

import styles from './CreateAgentOrInstallDropdown.module.css'

import {sidebarSettings} from 'src/components/App/SidebarPanel/SidebarPanel.slices'
import {useAppDispatch} from 'src/hooks/react-redux'

interface Props {
  className?: string
}

function CreateAgentOrInstallDropdown(props: Props) {
  useHint(addAgentPoolHint)
  const [showCreatePool, setShowCreatePool] = React.useState(false)
  const authDialog = useAuthAgentDialog()
  const canManageAgentPools = usePermission(Permission.MANAGE_AGENT_POOLS, ROOT_PROJECT_ID)

  const dispatch = useAppDispatch()

  const handleClick = useCallback((event: React.SyntheticEvent) => {
    event.preventDefault()
    event.stopPropagation()
  }, [])

  const handleCreatePoolClick = React.useCallback(() => {
    setShowCreatePool(true)
  }, [])

  const handleCloseCreatePool = React.useCallback(() => {
    setShowCreatePool(false)
  }, [])

  const installAgentItems: ListDataItem[] = isFullDistributions
    ? [
        {
          target: '_blank',
          rel: 'noreferrer',
          href: fullDistributions,
          label: 'Install Agent',
          className: styles.link,
          hoverClassName: styles.hoverLink,
        },
      ]
    : [
        {
          target: '_blank',
          rel: 'noopener',
          href: windowsInstallerUrl,
          label: 'Windows installer',
          className: styles.link,
          hoverClassName: styles.hoverLink,
        },
        {
          target: '_blank',
          rel: 'noreferrer',
          href: dockerAgentImageUrl,
          label: 'Docker image',
          className: styles.link,
          hoverClassName: styles.hoverLink,
        },
        {
          target: '_blank',
          rel: 'noreferrer',
          href: zipFileDistribution,
          label: 'Minimal ZIP file distribution',
          className: styles.link,
          hoverClassName: styles.hoverLink,
        },
        {
          target: '_blank',
          rel: 'noreferrer',
          href: isFullDistributions ? fullDistributions : fullZipFileDistribution,
          label: isFullDistributions ? 'Full distributions' : 'Full ZIP file distribution',
          className: styles.link,
          hoverClassName: styles.hoverLink,
        },
      ]

  if (authDialog.show != null) {
    installAgentItems.push({
      rgItemType: PopupMenu.ListProps.Type.SEPARATOR,
    })
  }
  installAgentItems.push({
    rgItemType: PopupMenu.ListProps.Type.CUSTOM,
    className: styles.text,
    template: (
      <div>
        {'See our '}
        <HelpLink
          url={resolveHelpURL(
            '?Setting+up+and+Running+Additional+Build+Agents#SettingupandRunningAdditionalBuildAgents-InstallingAdditionalBuildAgents',
          )}
        >
          {'documentation'}
        </HelpLink>
        {' for details.'}
      </div>
    ),
  })

  if (authDialog.show != null) {
    installAgentItems.push({
      label: 'Use authentication token...',
      onClick: authDialog.show,
    })
  }

  const data: ListDataItem[] = [
    {
      label: 'Create agent pool',
      onClick: handleCreatePoolClick,
      disabled: !canManageAgentPools,
    },
  ]
  if (!isFullDistributions) {
    data.push({
      rgItemType: PopupMenu.ListProps.Type.SEPARATOR,
    })
  }
  data.push(...installAgentItems)

  return (
    <>
      {authDialog.visible && <AgentAuthDialog onClose={authDialog.onClose} />}
      <span role="presentation" onClick={handleClick}>
        <Dropdown
          className={classNames(styles.dropdown, props.className)}
          anchor={({active}) => {
            const button = (
              <Button
                icon={AddIcon}
                active={active}
                aria-label={'Create agent pool or install agent'}
              />
            )
            return active ? (
              button
            ) : (
              <Tooltip title="Create agent pool or install agent">{button}</Tooltip>
            )
          }}
          onShow={() => dispatch(sidebarSettings.actions.setAutoCollapseDisabled(true))}
          onHide={() => dispatch(sidebarSettings.actions.setAutoCollapseDisabled(false))}
        >
          <PopupMenu data={data} shortcuts activateFirstItem closeOnSelect />
        </Dropdown>
      </span>
      {showCreatePool && (
        <CreateAgentPoolPopup
          hidden={!showCreatePool}
          onCreate={handleCloseCreatePool}
          onClose={handleCloseCreatePool}
        />
      )}
    </>
  )
}

export default CreateAgentOrInstallDropdown
