import {createSelector} from 'reselect'

import type {State} from '../../../../../reducers/types'
import {getHref, matchRoute, Routes} from '../../../../../routes'
import {getAllAgentPreviews} from '../../../../../selectors'
import {
  getAgentTypesHash,
  POOLS_SELECTION_NAME,
  UNAUTHORIZED_SELECTION_NAME,
} from '../../AgentsPages.selectors'
import type {
  ActiveItemFilter,
  AgentsRouteProps,
  AgentsTreeItemType,
  FlatAgentsTree,
  AgentsTreeItemTitle,
  AgentsTreeItemOverview,
  AgentsTreeItemSelection,
  AgentsTreeItemPool,
} from '../AgentsSidebar.types'
import {AgentTreeItemType, AgentTreeTitleType} from '../AgentsSidebar.types'
import {makeSidebarItems} from '../utils/makeSidebarItems'

import {getFavoriteAgentsPoolsLink} from './getFavoriteAgentsPoolsLink'
import {getFlatAgentsTree, getFlatFavoriteAgentsTree, getFlatSelectionAgentsTree} from './getFlat'

const favoriteAgentPoolsTitle: AgentsTreeItemTitle = {
  id: AgentTreeTitleType.FAVORITE,
  type: AgentTreeItemType.TITLE,
  editable: true,
  key: 'agent-pools-favorite-title',
  title: 'FAVORITES',
  level: 0,
}
function isAgentsTreeItemSelection(selectionTitle: any): selectionTitle is AgentsTreeItemSelection {
  return (
    typeof selectionTitle === 'object' &&
    selectionTitle != null &&
    'title' in selectionTitle &&
    'expanded' in selectionTitle &&
    selectionTitle.type === AgentTreeItemType.SELECTION
  )
}
const EXTENDED_ITEM_HEIGHT = 32
export const getSidebarItems = createSelector(
  getFavoriteAgentsPoolsLink,
  getFlatSelectionAgentsTree,
  getFlatAgentsTree,
  getFlatFavoriteAgentsTree,
  getAllAgentPreviews,
  getAgentTypesHash,
  (_: State, props: {route: AgentsRouteProps}) => props.route,
  (_: State, props: {pathname: string}) => props.pathname,
  (_: State, props: {isFavoriteEnabled: boolean}) => props.isFavoriteEnabled,
  (_: State, props: {hasFavoritePools: boolean}) => props.hasFavoritePools,
  (_: State, props: {hash: string}) => props.hash,
  (
    favoriteAgentsPoolsLink,
    flatSelectionAgentTree,
    flatAgentsTree,
    flatFavoriteAgentsTree,
    agentPreviewsHash,
    agentTypesHash,
    route,
    pathname,
    isFavoriteEnabled,
    hasFavoritePools,
    hash,
  ): [FlatAgentsTree, number, ActiveItemFilter | null] => {
    const items: Array<AgentsTreeItemType> = []

    if (flatSelectionAgentTree.length > 0) {
      const [selectionTitle, ...flatSelection] = flatSelectionAgentTree

      items.push({
        ...selectionTitle,
        height: items.length !== 0 ? EXTENDED_ITEM_HEIGHT : undefined,
      })
      if (
        isAgentsTreeItemSelection(selectionTitle) &&
        selectionTitle.title === UNAUTHORIZED_SELECTION_NAME &&
        selectionTitle.expanded
      ) {
        items.push({
          ...selectionTitle,
          key: 'unauthorized-overviiew',
          title: 'Overview',
          level: 1,
          href: getHref(Routes.AGENTS_UNAUTHORIZED),
          type: AgentTreeItemType.OVERVIEW,
          count: 0,
          disconnectedCount: 0,
          containsActive: false,
          focusable: true,
          expandable: false,
          active: matchRoute(Routes.AGENTS_UNAUTHORIZED, location.pathname) != null,
        } as AgentsTreeItemOverview)
      }
      items.push(...flatSelection)
    }

    if (isFavoriteEnabled && hasFavoritePools) {
      items.push(
        {
          ...favoriteAgentPoolsTitle,
          height: items.length !== 0 ? EXTENDED_ITEM_HEIGHT : undefined,
        },
        favoriteAgentsPoolsLink,
        ...flatFavoriteAgentsTree,
      )
    }

    if (flatAgentsTree.length > 0) {
      const [selectionTitle, ...flatSelection] = flatAgentsTree

      items.push({
        ...selectionTitle,
        height: items.length !== 0 ? EXTENDED_ITEM_HEIGHT : undefined,
        expandable: hasFavoritePools,
      } as AgentsTreeItemPool)
      if (
        isAgentsTreeItemSelection(selectionTitle) &&
        selectionTitle.title === POOLS_SELECTION_NAME &&
        selectionTitle.expanded
      ) {
        items.push({
          ...selectionTitle,
          key: 'agents-overview',
          title: 'Overview',
          level: hasFavoritePools ? 1 : 0,
          href: getHref(Routes.AGENTS_OVERVIEW),
          type: AgentTreeItemType.OVERVIEW,
          count: 0,
          disconnectedCount: 0,
          containsActive: false,
          focusable: true,
          expandable: false,
          active: matchRoute(Routes.AGENTS_OVERVIEW, location.pathname) != null,
        } as AgentsTreeItemOverview)
      }
      if (hasFavoritePools) {
        items.push(...flatSelection)
      } else {
        items.push(...flatSelection.map(item => ({...item, level: item.level - 1})))
      }
    }

    return makeSidebarItems(items, agentPreviewsHash, agentTypesHash, route, pathname, hash)
  },
)
