import {createSelector} from 'reselect'

import {getAgentsOverviewHref} from '../../../../../routes'
import {createAgentSelectionNode, POOLS_SELECTION_NAME} from '../../AgentsPages.selectors'
import {POOLS_SELECTION_ID} from '../AgentsSidebar.types'
import {matchAgentsTree} from '../utils/matches'

import {getAgentsTreeSearchState} from './getExpand'
import {sortedAgentsTree, sortedFavoriteAgentsTree, sortedSelectionsTree} from './sortedTree'

export const getMatchingSelectionsTree = createSelector(
  [sortedSelectionsTree, getAgentsTreeSearchState],
  matchAgentsTree,
)
const getAgentsPoolSelectionTree = createSelector([sortedAgentsTree], tree => {
  const selection = createAgentSelectionNode({
    id: POOLS_SELECTION_ID,
    name: POOLS_SELECTION_NAME,
    href: getAgentsOverviewHref(),
  })

  return {
    ...selection,
    disconnectedCount: tree.reduce((acc, pool) => acc + pool.disconnectedCount, 0),
    children: tree,
  }
})
export const getMatchingAgentsTree = createSelector(
  [getAgentsPoolSelectionTree, getAgentsTreeSearchState],
  (selection, searchState) => matchAgentsTree([selection], searchState),
)
export const getMatchingFavoriteAgentsTree = createSelector(
  [sortedFavoriteAgentsTree, getAgentsTreeSearchState],
  matchAgentsTree,
)
