import * as React from 'react'
import {Suspense, useEffect, useMemo} from 'react'
import {EntryPointContainer} from 'react-relay'

import {useEntryPointLoaderWithEnvironment} from '../../../../../../hooks/relay/useEntryPointLoaderWithEnvironment'
import CommonPopup from '../../../components/CommonPopup/CommonPopup'
import {EditAgentPoolFormEntryPoint} from '../../../components/EditAgentPoolForm/EditAgentPoolForm.entryPoint'

type Props = {
  onCreate: (arg0: void) => void
  onClose: (arg0: void) => void
  hidden: boolean
}
export default function CreateAgentPoolPopup({onCreate, onClose, hidden}: Props) {
  const [entryPoint, loadEntryPoint, disposeEntryPoint] = useEntryPointLoaderWithEnvironment(
    EditAgentPoolFormEntryPoint,
  )
  useEffect(() => {
    if (process.env.NODE_ENV === 'test') {
      // load entrypoint for storyshots
      loadEntryPoint(true)
    }
  }, [loadEntryPoint])
  const handleClose = React.useCallback(() => {
    onClose()
    disposeEntryPoint()
  }, [disposeEntryPoint, onClose])
  return useMemo(
    () => (
      <CommonPopup
        hidden={hidden}
        onShow={() => loadEntryPoint({})}
        onClose={handleClose}
        header={'New agent pool'}
        content={
          entryPoint && (
            <Suspense>
              <EntryPointContainer
                entryPointReference={entryPoint}
                props={{onUpdate: onCreate, onClose}}
              />
            </Suspense>
          )
        }
      />
    ),
    [hidden, handleClose, entryPoint, onCreate, onClose, loadEntryPoint],
  )
}
