import Loader from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import classNames from 'classnames'
import * as React from 'react'
import {Suspense, useState} from 'react'
import type {EntryPointProps, PreloadedQuery} from 'react-relay'
import {usePreloadedQuery} from 'react-relay'
import {useLocation} from 'react-router'
import CellMeasurer from 'react-virtualized/dist/es/CellMeasurer'
import type {RenderedRows} from 'react-virtualized/dist/es/List'
import type List from 'react-virtualized/dist/es/List'

import {useAgentId, useAgentPoolId, useAgentTypeId, useHash} from '../../../../hooks/routes'
import useEventCallback from '../../../../hooks/useEventCallback'
import usePrevious from '../../../../hooks/usePrevious'
import {getAgentPreviewsReady} from '../../../../selectors'
import {emptyArray} from '../../../../utils/empty'
import SidebarHeader from '../../../App/SidebarPanel/SidebarPanelContent/SidebarHeader/SidebarHeader'
import {useSidebarScroll} from '../../../App/SidebarPanel/SidebarPanelContent/SidebarPanelContent.hooks'
import {getSidebarSearchPlaceholder} from '../../../App/SidebarPanel/SidebarPanelContent/SidebarPanelContent.utils'
import SidebarPanelContentNoResults from '../../../App/SidebarPanel/SidebarPanelContent/SidebarPanelContentNoResults/SidebarPanelContentNoResults'
import type {TreeEvent} from '../../../common/Sidebar/Sidebar.types'
import {TreeEventType} from '../../../common/Sidebar/Sidebar.types'
import {keyboardToTreeEvent} from '../../../common/Sidebar/Sidebar.utils'
import SidebarSearch from '../../../common/SidebarSearch/SidebarSearch'
import type {VirtualizedTreeChildProps} from '../../../common/VirtualizedTree/VirtualizedTree'
import VirtualizedTree from '../../../common/VirtualizedTree/VirtualizedTree'
import InstallAgent from '../../PipelinesPages/EditPipelinePage/SettingsSidebarContent/JobSettingsSidebar/JobAgentRequirements/SelfHosted/InstallAgent/InstallAgent'
import {isPipelinesAgentPageEnabled} from '../../PipelinesPages/utils/featureToggles'
import type {AgentsPagesAgentTypesQuery} from '../__generated__/AgentsPagesAgentTypesQuery.graphql'
import type {AgentsPagesCanViewAgentDetailsFragment$key} from '../__generated__/AgentsPagesCanViewAgentDetailsFragment.graphql'
import {AgentPagePoolsSubscriber, useAgentPools} from '../AgentPagePoolsProvider'
import {AgentPoolsFavoriteDialog} from '../AgentPoolsFavoritePage/Dialog/AgentPoolsFavoriteDialog'
import {FAVORITE_DIALOG_SIDEBAR_ID} from '../AgentPoolsFavoritePage/Dialog/AgentPoolsFavoriteDialog.consts'
import {useAgentPoolFavoriteList} from '../AgentPoolsFavoritePage/hooks/useAgentPoolFavorite'
import {useIsAgentPoolFavoriteEnabled} from '../AgentPoolsFavoritePage/hooks/useIsAgentPoolFavoriteEnabled'
import {
  EXPAND_FAVORITE_SIDEBAR_STATE_KEY,
  EXPAND_SIDEBAR_STATE_KEY,
  getStoredAgentsTreeExpandState,
} from '../AgentsPages.effects'
import type {AgentsPagesQueries} from '../AgentsPages.queries'

import type {AgentsSidebarQuery} from './__generated__/AgentsSidebarQuery.graphql'
import {
  searchInAgentsTree,
  setAgentsTreeItemExpandState,
  setFavoriteAgentsTreeItemExpandState,
} from './AgentsSidebar.actions'
import {query} from './AgentsSidebar.queries'
import type {ActiveItemFilter, AgentsTreeItemType, FlatAgentsTree} from './AgentsSidebar.types'
import {AgentTreeItemCategory, AgentTreeItemType} from './AgentsSidebar.types'
import {findItemWithin, getIsEqualActiveItemFilters} from './AgentsSidebar.utils'
import AgentsSidebarItem, {INDEX_ATTRIBUTE} from './AgentsSidebarItem/AgentsSidebarItem'
import {
  getAgentsTreeSearchState,
  getDefaultFavoriteTreeExpand,
  getDefaultTreeExpand,
  getIsSearching,
} from './selectors/getExpand'
import {getInitialExpandState} from './selectors/getInitialExpandState'
import {getSidebarItems} from './selectors/getSidebarItems'
import {getPipelinesSidebarItems} from './selectors/pipelines/getPipelinesSidebarItems'
import CreateAgentOrInstallDropdown from './Title/CreateAgentOrInstallDropdown'

import styles from './AgentsSidebar.module.css'

import {sidebarSettings} from 'src/components/App/SidebarPanel/SidebarPanel.slices'
import SidebarHeaderShadow from 'src/components/App/SidebarPanel/SidebarPanelContent/SidebarHeaderShadow/SidebarHeaderShadow'
import {useAppDispatch, useAppSelector} from 'src/hooks/react-redux'

const ITEM_HEIGHT = 24
const SEARCH_INPUT_ID = 'agents-sidebar-search'

type BaseProps = {
  className?: string
  path?: string
  width: number
}
type Props = BaseProps & {
  agentTypesQueryRef: PreloadedQuery<AgentsPagesAgentTypesQuery>
  dataKey: AgentsPagesCanViewAgentDetailsFragment$key | null
}

function AgentsSidebarComponent({
  className,
  width: sidebarWidth,
  favoritePools,
  agentTypesQueryRef,
  dataKey,
}: Props & {
  favoritePools: number[]
}) {
  const prevActiveItemFilter = React.useRef<ActiveItemFilter | null>(null)
  const pools = useAgentPools()
  const [searchActive, setSearchActive] = useState(false)
  const [scrollState, onScroll] = useSidebarScroll()

  const location = useLocation()
  const hash = useHash()
  const agentId = useAgentId()
  const agentPoolId = useAgentPoolId()
  const agentTypeId = useAgentTypeId()
  const urlProps = React.useMemo(
    () => ({
      agentId,
      agentPoolId,
      agentTypeId,
    }),
    [agentId, agentPoolId, agentTypeId],
  )
  const initialUrlProps = React.useRef(urlProps)
  const initialStoredExpandState = React.useRef(
    getStoredAgentsTreeExpandState(EXPAND_SIDEBAR_STATE_KEY),
  )
  const initialStoredFavoriteExpandState = React.useRef(
    getStoredAgentsTreeExpandState(EXPAND_FAVORITE_SIDEBAR_STATE_KEY),
  )
  const dispatch = useAppDispatch()
  const allAgentsDataReady = useAppSelector(state => getAgentPreviewsReady(state))
  const isFavoriteEnabled = useIsAgentPoolFavoriteEnabled()
  const hasFavoritePools = favoritePools.length > 0
  const [items, activeItemIndex, activeItemFilter] = useAppSelector(state => {
    if (allAgentsDataReady) {
      const defaultFavoriteExpandState = getDefaultFavoriteTreeExpand(
        initialStoredFavoriteExpandState.current,
        getInitialExpandState(state, {
          pools,
          route: initialUrlProps.current,
        }),
      )
      const defaultExpandState = getDefaultTreeExpand(
        initialStoredExpandState.current,
        getInitialExpandState(state, {
          pools,
          route: initialUrlProps.current,
        }),
      )

      if (isPipelinesAgentPageEnabled()) {
        return getPipelinesSidebarItems(state, {
          pools,
          defaultExpandState,
          route: urlProps,
          pathname: location.pathname,
          hash,
        })
      }

      return getSidebarItems(state, {
        pools,
        defaultExpandState,
        defaultFavoriteExpandState,
        isFavoriteEnabled,
        hasFavoritePools,
        favoritePools,
        route: urlProps,
        pathname: location.pathname,
        hash,
      })
    }

    return null
  }) ?? [emptyArray as FlatAgentsTree, -1, null]

  React.useEffect(() => {
    if (!getIsEqualActiveItemFilters(activeItemFilter, prevActiveItemFilter.current)) {
      prevActiveItemFilter.current = activeItemFilter
    }
  }, [activeItemFilter])

  const isSearching = useAppSelector(getIsSearching)
  const searchQuery = useAppSelector(state => getAgentsTreeSearchState(state).searchQuery)
  const previousSearchQuery = usePrevious(searchQuery)
  const firstMatchingItemIndex = React.useMemo(
    () =>
      isSearching
        ? items.findIndex(
            item =>
              (item.type === AgentTreeItemType.AGENT && item.matching) ||
              (item.type === AgentTreeItemType.POOL && item.matching),
          )
        : -1,
    [isSearching, items],
  )
  const collapsed = useAppSelector(state => state.sidebarSettings.collapsed)
  const pageStartIndexRef = React.useRef(-1)
  const pageEndIndexRef = React.useRef(-1)
  const listRef = React.useRef<List>(null)
  const wrapperRef = React.useRef<HTMLDivElement>(null)
  const searchInputRef = React.useRef<HTMLInputElement | null>(null)
  const setExpandState = React.useCallback(
    (item: AgentsTreeItemType, expanded: boolean) => {
      if (
        item.type === AgentTreeItemType.POOL ||
        item.type === AgentTreeItemType.SELECTION ||
        item.type === AgentTreeItemType.AGENT_TYPE ||
        item.type === AgentTreeItemType.FOLDER
      ) {
        const expandAction =
          item.category === AgentTreeItemCategory.MAIN
            ? setAgentsTreeItemExpandState
            : setFavoriteAgentsTreeItemExpandState

        dispatch(expandAction(item.id, item.type, expanded))
      }
    },
    [dispatch],
  )

  const renderItem = React.useCallback(
    ({
      item,
      index,
      style,
      height,
      width,
      indent,
      parent,
      cache,
    }: VirtualizedTreeChildProps<AgentsTreeItemType>) => {
      const props = {
        index,
        style,
        height,
        width,
        indent,
        parent,
        cache,
        setExpandState,
        itemKey: item.key,
        dataKey,
      }

      return (
        <CellMeasurer cache={cache} key={item.key} parent={parent} rowIndex={index}>
          <div>
            <AgentsSidebarItem
              {...props}
              {...item}
              key={item.key}
              hasFavoritePools={hasFavoritePools}
            />
          </div>
        </CellMeasurer>
      )
    },
    [setExpandState, dataKey, hasFavoritePools],
  )

  const scrollToItem = (itemIndex: number): void => {
    if (itemIndex < 0) {
      return
    }

    listRef.current?.scrollToRow(itemIndex)
  }

  const focusItem = (itemIndex: number): void => {
    if (itemIndex < 0) {
      return
    }

    listRef.current?.scrollToRow(itemIndex)
    requestAnimationFrame(() => findItemWithin(itemIndex, wrapperRef.current)?.focus())
  }

  React.useEffect(() => {
    if (previousSearchQuery !== searchQuery && previousSearchQuery !== '') {
      scrollToItem(firstMatchingItemIndex)
    }
  }, [searchQuery, previousSearchQuery, firstMatchingItemIndex])
  const onRowsRendered = React.useCallback(
    ({startIndex, stopIndex}: RenderedRows) => {
      pageStartIndexRef.current = startIndex
      pageEndIndexRef.current = stopIndex
    },
    [pageStartIndexRef, pageEndIndexRef],
  )

  const onTreeEvent = React.useCallback(
    (treeEvent: TreeEvent) => {
      if (treeEvent.type === TreeEventType.EVENT_TYPE_FOCUS) {
        if (treeEvent.index < 0) {
          searchInputRef.current?.focus()
        } else if (treeEvent.index < items.length) {
          focusItem(treeEvent.index)
        }

        return
      }

      const item = items[treeEvent.index]

      if (
        treeEvent.type === TreeEventType.EVENT_TYPE_EXPAND ||
        treeEvent.type === TreeEventType.EVENT_TYPE_COLLAPSE
      ) {
        if (item.type === AgentTreeItemType.SELECTION || item.type === AgentTreeItemType.POOL) {
          setExpandState(item, treeEvent.type === TreeEventType.EVENT_TYPE_EXPAND)
        } else if (item.type === AgentTreeItemType.AGENT_TYPE) {
          setExpandState(item, treeEvent.type === TreeEventType.EVENT_TYPE_EXPAND)
        }
      }

      if (treeEvent.type === TreeEventType.EVENT_TYPE_SELECT) {
        findItemWithin(treeEvent.index, wrapperRef.current)?.querySelector('a')?.click()
      }
    },
    [items, setExpandState],
  )
  const onSearchKeyDown = useEventCallback((e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown' || e.key === 'Enter' || e.key === 'PageDown') {
      const treeEvent = keyboardToTreeEvent(
        e,
        items,
        firstMatchingItemIndex > -1 ? firstMatchingItemIndex : pageStartIndexRef.current,
        pageStartIndexRef.current,
        pageEndIndexRef.current,
      )

      if (treeEvent != null) {
        onTreeEvent(treeEvent)
      }
    }
  })
  const changeSidebarSearchActive = React.useCallback(
    (active: boolean) => {
      setSearchActive(active)
      dispatch(sidebarSettings.actions.setAutoCollapseDisabled(active))

      if (!active) {
        dispatch(searchInAgentsTree(''))
      }
    },
    [dispatch],
  )
  React.useEffect(() => {
    if (collapsed && searchActive) {
      changeSidebarSearchActive(false)
    }
  }, [collapsed, searchActive, changeSidebarSearchActive])
  const onItemKeyDown = React.useCallback(
    (e: React.KeyboardEvent) => {
      const {target} = e
      if (
        !(target instanceof HTMLElement) ||
        target.tagName === 'INPUT' ||
        target.tagName === 'TEXTAREA' ||
        target.isContentEditable
      ) {
        return
      }

      // Character, shift is OK
      if (e.key === 'Backspace' || (e.key.length === 1 && !e.ctrlKey && !e.metaKey && !e.altKey)) {
        searchInputRef.current?.focus()
        return
      }

      const focusedIndex = parseInt((e.target as Element).getAttribute(INDEX_ATTRIBUTE)!, 10)
      const treeEvent = keyboardToTreeEvent(
        e,
        items,
        focusedIndex,
        pageStartIndexRef.current,
        pageEndIndexRef.current,
      )

      if (treeEvent != null) {
        onTreeEvent(treeEvent)
      }
    },
    [items, onTreeEvent],
  )

  const shouldScrollToIndex = !getIsEqualActiveItemFilters(
    activeItemFilter,
    prevActiveItemFilter.current,
  )

  const calculateItemHeight = React.useCallback(
    (item: AgentsTreeItemType) => item.height ?? ITEM_HEIGHT,
    [],
  )

  const renderSearch = () => (
    <SidebarSearch
      id={SEARCH_INPUT_ID}
      onKeyDown={onSearchKeyDown}
      inputRef={el => {
        if (el != null) {
          searchInputRef.current = el
        }
      }}
      searchQuery={searchQuery}
      searchActive={searchActive}
      changeSidebarSearchQuery={search => dispatch(searchInAgentsTree(search))}
      changeSidebarSearchActive={changeSidebarSearchActive}
      placeholder={getSidebarSearchPlaceholder(sidebarWidth, 'Search by name')}
    />
  )

  return (
    <>
      {isFavoriteEnabled && (
        <AgentPoolsFavoriteDialog
          id={FAVORITE_DIALOG_SIDEBAR_ID}
          agentTypesQueryRef={agentTypesQueryRef}
        />
      )}
      <div
        className={classNames(styles.sidebar, className)}
        ref={wrapperRef}
        data-test-agents-sidebar
      >
        <SidebarHeaderShadow
          sidebarCollapsed={collapsed}
          showShadow={!collapsed && scrollState?.isScrollAtStart === false}
        >
          <SidebarHeader
            sidebarName={'Agents'}
            className={styles.header}
            search={renderSearch()}
            headerButton={
              isPipelinesAgentPageEnabled() ? (
                <InstallAgent inline primary={false} />
              ) : (
                <Suspense>
                  <CreateAgentOrInstallDropdown />
                </Suspense>
              )
            }
          />
        </SidebarHeaderShadow>

        {!collapsed && isSearching && items.length === 0 && <SidebarPanelContentNoResults />}
        {collapsed ? null : allAgentsDataReady ? (
          <VirtualizedTree
            ariaLabel={'Agents'}
            className={styles.tree}
            flatItems={items}
            itemHeight={calculateItemHeight}
            firstLevelIndent={2}
            levelIndent={16}
            scrollToIndex={activeItemIndex}
            shouldScrollToIndex={shouldScrollToIndex}
            onKeyDown={onItemKeyDown}
            ref={listRef}
            onRowsRendered={onRowsRendered}
            onScroll={onScroll}
            tabIndex={-1}
          >
            {renderItem}
          </VirtualizedTree>
        ) : (
          <div className={styles.loader}>
            <Loader />
            <span className={styles.loaderText}> {'Agents data is loading...'}</span>
          </div>
        )}
      </div>
    </>
  )
}

const AgentsSidebar = React.memo(AgentsSidebarComponent)

type Queries = AgentsPagesQueries & {main: AgentsSidebarQuery}
export default function AgentsSidebarRelayContainer({
  queries,
  props,
}: EntryPointProps<Queries, {}, BaseProps, {}>) {
  const favoritePools = useAgentPoolFavoriteList()
  const data = usePreloadedQuery(query, queries.main)

  return (
    <AgentPagePoolsSubscriber agentTypesQueryRef={queries.agentTypes}>
      <AgentsSidebar
        {...props}
        favoritePools={favoritePools}
        agentTypesQueryRef={queries.agentTypes}
        dataKey={data}
      />
    </AgentPagePoolsSubscriber>
  )
}
export type AgentsSidebarRelayContainerComponent = typeof AgentsSidebarRelayContainer
