import {stringifyId} from '../../../../../types'
import type {AgentsTreeExpandState} from '../../AgentsPages.types'
import type {
  AgentBranch,
  AgentBranchId,
  AgentsTree,
  AgentsTreeAgentNode,
  AgentsTreeAgentPoolNode,
  AgentsTreeAgentSelectionNode,
  AgentsTreeAgentTypeNode,
  AgentsTreeFolderTypeNode,
  AgentsTreeItemAgent,
  AgentsTreeItemAgentType,
  AgentsTreeItemFolder,
  AgentsTreeItemPool,
  AgentsTreeItemSelection,
  AgentsTreeItemType,
  AgentTreeItemCategory,
} from '../AgentsSidebar.types'
import {AgentTreeItemType} from '../AgentsSidebar.types'

import LinuxIcon from 'src/svg/os-linux.svg'
import MacOSIcon from 'src/svg/os-mac.svg'
import WindowsIcon from 'src/svg/os-windows.svg'

export function makeFlatAgentsTree(
  agentsTree: AgentsTree,
  expandState: AgentsTreeExpandState,
  isSearching: boolean,
  category: AgentTreeItemCategory,
) {
  type FlatAgentTypeItem = AgentsTreeItemAgentType | AgentsTreeItemAgent | AgentsTreeItemFolder

  const getExpanded = (
    containsMatching: boolean | undefined,
    itemType: AgentBranch,
    itemId?: AgentBranchId,
  ) => {
    // For the search mode the item containing mathing items is expanded by default
    if (isSearching) {
      if (expandState[itemType]?.[itemId!] != null) {
        return Boolean(expandState[itemType]?.[itemId!])
      }

      return containsMatching
    }

    // For the regular only the basic expand state matters
    return Boolean(expandState[itemType]?.[itemId!])
  }

  const flattenAgent = (
    node: AgentsTreeAgentNode,
    level: number,
  ): ReadonlyArray<AgentsTreeItemAgent> => {
    const {id, type, title, name, busy, connected, enabled, authorized, osType, cloud, matching} =
      node
    return [
      {
        id,
        category,
        key: `${category}-agent-${type}-${stringifyId(id)}`,
        type,
        title,
        name,
        level,
        busy,
        connected,
        enabled,
        authorized,
        osType,
        cloud,
        active: false,
        focusable: true,
        matching,
      },
    ]
  }

  const flattenAgentType = (
    node: AgentsTreeAgentTypeNode,
    level: number,
    isFolder = false,
  ): ReadonlyArray<FlatAgentTypeItem> => {
    const {
      type,
      id,
      title,
      count,
      busyCount,
      disconnectedCount,
      children,
      matching,
      containsMatching,
      osType,
    } = node
    function getIcon() {
      switch (osType) {
        case 'Linux':
          return LinuxIcon
        case 'macOS':
          return MacOSIcon
        case 'Windows':
          return WindowsIcon
        default:
          return null
      }
    }

    const agentTypeItem: AgentsTreeItemAgentType = {
      type: AgentTreeItemType.AGENT_TYPE,
      key: `${category}-agent-type-${stringifyId(id)}`,
      category,
      id,
      title,
      level,
      count,
      busyCount,
      disconnectedCount,
      matching,
      expanded: getExpanded(containsMatching, type, id),
      active: false,
      containsActive: false,
      focusable: true,
      osType,
      expandable: children.length > 0,
      icon: isFolder ? getIcon() : null,
    }
    const flatBranch: FlatAgentTypeItem[] = [agentTypeItem]

    if (agentTypeItem.expanded === true) {
      for (const child of children) {
        flatBranch.push(...flattenAgent(child, level + 1))
      }
    }

    return flatBranch
  }

  const flattenAgentPool = (
    node: AgentsTreeAgentPoolNode,
    level: number,
  ): ReadonlyArray<AgentsTreeItemPool | FlatAgentTypeItem> => {
    const {
      id,
      type,
      title,
      count,
      busyCount,
      disconnectedCount,
      containsMatching,
      matching,
      children,
    } = node
    const poolItem: AgentsTreeItemPool = {
      id,
      category,
      key: `${category}-agent-pool-${stringifyId(id)}`,
      type: AgentTreeItemType.POOL,
      title,
      level,
      count,
      busyCount,
      disconnectedCount,
      matching,
      expanded: getExpanded(containsMatching, type, id),
      active: false,
      containsActive: false,
      focusable: true,
      expandable: true,
    }
    let flatBranch: (AgentsTreeItemPool | FlatAgentTypeItem)[] = [poolItem]

    if (poolItem.expanded === true) {
      for (const child of children) {
        flatBranch = flatBranch.concat(
          child.type === AgentTreeItemType.AGENT
            ? flattenAgent(child, level + 1)
            : flattenAgentType(child, level + 1),
        )
      }
    }

    return flatBranch
  }

  const flattenFolder = (
    node: AgentsTreeFolderTypeNode,
    level: number,
  ): ReadonlyArray<FlatAgentTypeItem> => {
    const {
      type,
      id,
      title,
      count,
      busyCount,
      disconnectedCount,
      children,
      matching,
      containsMatching,
    } = node

    const agentFolderItem: AgentsTreeItemFolder = {
      type: AgentTreeItemType.FOLDER,
      key: `${category}-agent-folder-${stringifyId(id)}`,
      category,
      id,
      title,
      level,
      count,
      busyCount,
      disconnectedCount,
      matching,
      expanded: getExpanded(containsMatching, type, id),
      active: false,
      containsActive: false,
      focusable: true,
      expandable: children.length > 0,
    }
    const flatBranch: FlatAgentTypeItem[] = [agentFolderItem]

    if (agentFolderItem.expanded === true) {
      for (const child of children) {
        if (child.type === AgentTreeItemType.AGENT_TYPE) {
          flatBranch.push(...flattenAgentType(child, level + 1, true))
        } else if (child.type === AgentTreeItemType.FOLDER) {
          flatBranch.push(...flattenFolder(child, level + 1))
        } else if (child.type === AgentTreeItemType.AGENT) {
          flatBranch.push(...flattenAgent(child, level + 1))
        }
      }
    }

    return flatBranch
  }

  const flattenAgentSelection = (
    node: AgentsTreeAgentSelectionNode,
    level: number,
  ): ReadonlyArray<AgentsTreeItemSelection | FlatAgentTypeItem | AgentsTreeItemPool> => {
    const {id, href, type, title, count, disconnectedCount, children, containsMatching} = node
    const selectionItem: AgentsTreeItemSelection = {
      id,
      category,
      key: `${category}-agent-selection-${stringifyId(id)}`,
      type: AgentTreeItemType.SELECTION,
      title,
      level,
      count,
      disconnectedCount,
      href,
      expanded: getExpanded(containsMatching, type, id),
      active: false,
      containsActive: false,
      focusable: true,
      expandable: true,
    }
    let flatBranch: (AgentsTreeItemSelection | FlatAgentTypeItem | AgentsTreeItemPool)[] = [
      selectionItem,
    ]

    if (selectionItem.expanded === true) {
      for (const child of children) {
        if (child.type === AgentTreeItemType.AGENT) {
          flatBranch = flatBranch.concat(flattenAgent(child, level + 1))
        } else if (child.type === AgentTreeItemType.POOL) {
          flatBranch = flatBranch.concat(flattenAgentPool(child, level + 1))
        } else if (child.type === AgentTreeItemType.FOLDER) {
          flatBranch = flatBranch.concat(flattenFolder(child, level + 1))
        }
      }
    }
    return flatBranch
  }

  let flatTree: AgentsTreeItemType[] = []

  for (const node of agentsTree) {
    if (node.type === AgentTreeItemType.POOL) {
      flatTree = flatTree.concat(flattenAgentPool(node, 0))
    } else if (node.type === AgentTreeItemType.SELECTION) {
      flatTree = flatTree.concat(flattenAgentSelection(node, 0))
    }
  }

  return flatTree
}
