import {createSelector} from 'reselect'

import {AgentTreeItemCategory} from '../AgentsSidebar.types'
import {makeFlatAgentsTree} from '../utils/makeFlatAgentsTree'

import {getExpandState, getFavoriteExpandState, getIsSearching} from './getExpand'
import {
  getMatchingAgentsTree,
  getMatchingFavoriteAgentsTree,
  getMatchingSelectionsTree,
} from './matchingTree'

export const getFlatSelectionAgentsTree = createSelector(
  [getMatchingSelectionsTree, getExpandState, getIsSearching, () => AgentTreeItemCategory.MAIN],
  makeFlatAgentsTree,
)
export const getFlatAgentsTree = createSelector(
  [getMatchingAgentsTree, getExpandState, getIsSearching, () => AgentTreeItemCategory.MAIN],
  makeFlatAgentsTree,
)
export const getFlatFavoriteAgentsTree = createSelector(
  [
    getMatchingFavoriteAgentsTree,
    getFavoriteExpandState,
    getIsSearching,
    () => AgentTreeItemCategory.FAVORITE,
  ],
  makeFlatAgentsTree,
)
