import type {ReactNode} from 'react'
import {createContext, useContext} from 'react'
import type {PreloadedQuery} from 'react-relay'
import {usePreloadedQuery} from 'react-relay'

import Loader from '../../common/Loader/Loader'

import type {AgentsPagesAgentTypesQuery} from './__generated__/AgentsPagesAgentTypesQuery.graphql'
import {useNativeSubscribeOnAgentTypes, useSubscribeOnAgentTypes} from './AgentsPages.hooks'
import {agentTypesQuery} from './AgentsPages.queries'
import type {AgentPoolArray} from './AgentsPages.selectors'

const PoolsContext = createContext<AgentPoolArray>([])

export const useAgentPools = () => useContext(PoolsContext)

function AgentPageRestPoolsProvider(props: {
  queryRef: PreloadedQuery<AgentsPagesAgentTypesQuery>
  children: ReactNode
}) {
  const {queryRef, children} = props
  const agentTypesQueryResponse = usePreloadedQuery(agentTypesQuery, queryRef)

  const skip =
    agentTypesQueryResponse.agentPoolsRest?.agentPool == null ||
    agentTypesQueryResponse.agentPoolsRest.agentPool.length > 0
  const nativePools = useNativeSubscribeOnAgentTypes(skip)

  if (agentTypesQueryResponse?.agentPoolsRest?.agentPool == null) {
    return <Loader />
  }

  const hasPermission = agentTypesQueryResponse.agentPoolsRest.agentPool.length > 0

  if (hasPermission) {
    return (
      <PoolsContext.Provider value={agentTypesQueryResponse.agentPoolsRest.agentPool}>
        {children}
      </PoolsContext.Provider>
    )
  }

  if (nativePools == null) {
    return <Loader />
  }

  return <PoolsContext.Provider value={nativePools}>{children}</PoolsContext.Provider>
}

export function AgentPagePoolsSubscriber(props: {
  agentTypesQueryRef: PreloadedQuery<AgentsPagesAgentTypesQuery>
  children: ReactNode
}) {
  const {agentTypesQueryRef, children} = props
  const queryRef = useSubscribeOnAgentTypes(agentTypesQueryRef)

  return (
    queryRef != null && (
      <AgentPageRestPoolsProvider queryRef={queryRef}>{children}</AgentPageRestPoolsProvider>
    )
  )
}
