import {Content, Header} from '@jetbrains/ring-ui-built/components/island/island'
import type {PopupAttrs} from '@jetbrains/ring-ui-built/components/popup/popup'
import classNames from 'classnames'
import * as React from 'react'

import Popup from '../../../../common/Popup/Popup.lazy'

import styles from './CommonPopup.module.css'

type Props = {
  className?: string
  header: React.ReactNode
  content: React.ReactNode
  onClose: PopupAttrs['onCloseAttempt']
} & Partial<PopupAttrs>

function CommonPopup({className, header, content, onClose, ...popupProps}: Props) {
  return (
    <Popup
      className={classNames(className, styles.popup)}
      onCloseAttempt={onClose}
      dontCloseOnAnchorClick
      {...popupProps}
    >
      <Header className={styles.header}>{header}</Header>
      <Content>{content}</Content>
    </Popup>
  )
}

export default React.memo(CommonPopup)
