import {createSelector} from 'reselect'

import type {State} from '../../../../../reducers/types'
import {getAllAgentPreviews} from '../../../../../selectors'
import type {AgentPoolId, AgentTypeId} from '../../../../../types'
import {getEmptyHash} from '../../../../../utils/empty'
import {keyValue} from '../../../../../utils/object'
import {getAgentTypesHash} from '../../AgentsPages.selectors'
import type {AgentsTreeExpandState} from '../../AgentsPages.types'
import type {AgentBranchId, AgentSelectionId, AgentsRouteProps} from '../AgentsSidebar.types'
import {AgentTreeItemType} from '../AgentsSidebar.types'

export const getInitialExpandState = createSelector(
  getAllAgentPreviews,
  getAgentTypesHash,
  (_: State, props: {route: AgentsRouteProps}) => props.route,
  (
    agentPreviewsHash,
    agentTypesHash,
    {agentId, agentTypeId, agentPoolId},
  ): AgentsTreeExpandState => {
    let expandedAgentTypeId: AgentTypeId | null | undefined = null
    let expandedAgentPoolId: AgentPoolId | null | undefined = null
    let expandedAgentSelectionId: AgentSelectionId | null | undefined = null

    if (agentId != null && agentPreviewsHash[agentId] != null) {
      const agent = agentPreviewsHash[agentId]

      if (agent != null) {
        const agentType = agentTypesHash[agent.typeId]

        if (agentType?.isCloud) {
          expandedAgentTypeId = agentType.id
        }
      }

      if (agent?.authorized === false) {
        expandedAgentSelectionId = 'unauthorized-agents'
      } else {
        expandedAgentPoolId = agentPreviewsHash[agentId]?.pool.id
      }
    }

    if (agentTypeId != null && agentTypesHash[agentTypeId] != null) {
      expandedAgentTypeId = agentTypeId
      expandedAgentPoolId = agentTypesHash[agentTypeId]?.agentPool.id
    }

    if (agentPoolId != null) {
      expandedAgentPoolId = agentPoolId
    }

    return {
      [AgentTreeItemType.AGENT_TYPE]: expandedAgentTypeId
        ? keyValue<AgentBranchId, boolean>(expandedAgentTypeId, true)
        : getEmptyHash(),
      [AgentTreeItemType.SELECTION]: expandedAgentSelectionId
        ? keyValue<AgentBranchId, boolean>(expandedAgentSelectionId, true)
        : getEmptyHash(),
      [AgentTreeItemType.POOL]: expandedAgentPoolId
        ? keyValue<AgentBranchId, boolean>(expandedAgentPoolId, true)
        : getEmptyHash(),
    }
  },
)
