import {useCallback, useEffect, useRef} from 'react'
import {fetchQuery, useRelayEnvironment} from 'react-relay'
import {createOperationDescriptor, getRequest} from 'relay-runtime'
import type {RelayObservable} from 'relay-runtime/lib/network/RelayObservable'
import type {GraphQLTaggedNode} from 'relay-runtime/lib/query/RelayModernGraphQLTag'
import type {OperationType} from 'relay-runtime/lib/util/RelayRuntimeTypes'

import type {Unsubscribe} from '../../utils/subscriber'

export function useOnDemandQuery<T extends OperationType>(query: GraphQLTaggedNode) {
  const environment = useRelayEnvironment()
  const cleanups = useRef<Unsubscribe[]>([])
  useEffect(
    () => () => {
      cleanups.current.forEach(cleanup => cleanup())
    },
    [],
  )

  return useCallback(
    (variables: T['variables'], force?: boolean): RelayObservable<T['response']> => {
      const result = fetchQuery(environment, query, variables, {
        fetchPolicy: force ? 'network-only' : 'store-or-network',
        networkCacheConfig: {metadata: {isRefetch: force}},
      })
      cleanups.current.push(
        environment.retain(createOperationDescriptor(getRequest(query), variables)).dispose,
        result.subscribe({}).unsubscribe,
      )
      return result
    },
    [environment, query],
  )
}
