import {createSelector} from 'reselect'

import type {State} from '../../../../../../reducers/types'
import {getAllAgentPreviews} from '../../../../../../selectors'
import {getAgentTypesHash} from '../../../AgentsPages.selectors'
import type {ActiveItemFilter, AgentsRouteProps, FlatAgentsTree} from '../../AgentsSidebar.types'
import {makeSidebarItems} from '../../utils/makeSidebarItems'

import {getPipelinesFlatAgentsTree} from './getPipelinesFlat'

export const getPipelinesSidebarItems = createSelector(
  getPipelinesFlatAgentsTree,
  getAllAgentPreviews,
  getAgentTypesHash,
  (_: State, props: {route: AgentsRouteProps}) => props.route,
  (_: State, props: {pathname: string}) => props.pathname,
  (_: State, props: {hash: string}) => props.hash,
  (
    flatAgentsTree,
    agentPreviewsHash,
    agentTypesHash,
    route,
    pathname,
    hash,
  ): [FlatAgentsTree, number, ActiveItemFilter | null] =>
    makeSidebarItems(flatAgentsTree, agentPreviewsHash, agentTypesHash, route, pathname, hash),
)
