import Routes, {ALL_POOLS_HASH, matchRoute} from '../../../../../routes'
import type {AgentPreviewsHash} from '../../../../../types'
import type {WritableAgentTypesHash} from '../../AgentsPages.selectors'
import {
  type ActiveItemFilter,
  type AgentsTreeItemType,
  type AgentsRouteProps,
  AgentTreeItemCategory,
  AgentTreeItemType,
  type FlatAgentsTree,
  POOLS_SELECTION_ID,
  UNAUTHORIZED_AGENTS_SELECTION_ID,
} from '../AgentsSidebar.types'

export function makeSidebarItems(
  items: Array<AgentsTreeItemType>,
  agentPreviewsHash: AgentPreviewsHash,
  agentTypesHash: WritableAgentTypesHash,
  route: AgentsRouteProps,
  pathname: string,
  hash: string,
): [FlatAgentsTree, number, ActiveItemFilter | null] {
  const {agentId, agentTypeId, agentPoolId} = route
  let activeItemFilter: ActiveItemFilter = {
    id: POOLS_SELECTION_ID,
    type: AgentTreeItemType.SELECTION,
  }

  if (agentId != null) {
    activeItemFilter = {
      id: agentId,
      type: AgentTreeItemType.AGENT,
    }
  } else if (agentTypeId != null) {
    activeItemFilter = {
      id: agentTypeId,
      type: AgentTreeItemType.AGENT_TYPE,
    }
  } else if (agentPoolId != null) {
    activeItemFilter = {
      id: agentPoolId,
      type: AgentTreeItemType.POOL,
    }
  } else if (
    matchRoute(Routes.AGENTS, pathname) ||
    matchRoute(Routes.AGENTS_OVERVIEW, pathname) ||
    matchRoute(Routes.DISCONNECTED_AGENTS_OVERVIEW, pathname)
  ) {
    activeItemFilter = {
      id: POOLS_SELECTION_ID,
      type: AgentTreeItemType.SELECTION,
    }
  } else if (matchRoute(Routes.FAVORITE_AGENT_POOLS, pathname)) {
    activeItemFilter = {
      id: 'favorite-agents-link',
      type: AgentTreeItemType.FAVORITE_LINK,
    }
  } else if (matchRoute(Routes.AGENTS_UNAUTHORIZED, pathname)) {
    activeItemFilter = {
      id: UNAUTHORIZED_AGENTS_SELECTION_ID,
      type: AgentTreeItemType.SELECTION,
    }
  }

  const getItemIndex: (arg0: ActiveItemFilter) => number = filter =>
    items.findIndex(item => {
      if (item.type === filter.type && item.id === filter.id) {
        if (
          item.type === AgentTreeItemType.POOL ||
          item.type === AgentTreeItemType.AGENT ||
          item.type === AgentTreeItemType.AGENT_TYPE
        ) {
          return (
            (hash !== ALL_POOLS_HASH && item.category === AgentTreeItemCategory.FAVORITE) ||
            item.category === AgentTreeItemCategory.MAIN
          )
        } else {
          return true
        }
      }

      return false
    })

  const getParentFilter = (filter: ActiveItemFilter): ActiveItemFilter | null => {
    if (filter.type === AgentTreeItemType.AGENT_TYPE) {
      const agentType = agentTypesHash[filter.id]

      if (agentType != null) {
        return {
          id: agentType.agentPool.id,
          type: AgentTreeItemType.POOL,
        }
      }
    } else if (filter.type === AgentTreeItemType.AGENT) {
      const preview = agentPreviewsHash[filter.id]

      if (preview == null) {
        return null
      }

      if (preview.authorized === false) {
        return {
          id: UNAUTHORIZED_AGENTS_SELECTION_ID,
          type: AgentTreeItemType.SELECTION,
        }
      }

      const agentType = agentTypesHash[preview.typeId]

      if (agentType?.isCloud) {
        return {
          id: agentType.id,
          type: AgentTreeItemType.AGENT_TYPE,
        }
      }

      return {
        id: preview.pool.id,
        type: AgentTreeItemType.POOL,
      }
    }

    return null
  }

  let activeItemIndex = getItemIndex(activeItemFilter)
  let parentItemFilter: ActiveItemFilter | null = null
  let isParentItemActive = false

  while (activeItemIndex === -1 && activeItemFilter.type !== AgentTreeItemType.POOL) {
    parentItemFilter = getParentFilter(parentItemFilter || activeItemFilter)

    if (parentItemFilter == null) {
      break
    }

    activeItemIndex = getItemIndex(parentItemFilter)
    isParentItemActive = true
  }

  function makeActive(item: AgentsTreeItemType) {
    switch (item?.type) {
      // can't use fallthrough because of types complexity
      case AgentTreeItemType.POOL:
        return parentItemFilter ? {...item, containsActive: true} : {...item, active: true}

      case AgentTreeItemType.SELECTION:
        return parentItemFilter ? {...item, containsActive: true} : {...item, active: true}

      case AgentTreeItemType.AGENT_TYPE:
        return parentItemFilter ? {...item, containsActive: true} : {...item, active: true}

      case AgentTreeItemType.AGENT:
        return {...item, active: true}

      case AgentTreeItemType.FAVORITE_LINK:
        return {...item, active: true}

      case AgentTreeItemType.FOLDER:
        return parentItemFilter ? {...item, containsActive: true} : {...item, active: true}

      default:
        return item
    }
  }

  const activeItem = items[activeItemIndex]

  const sidebarItems =
    activeItem != null
      ? items.map((item, index) => (index === activeItemIndex ? makeActive(item) : item))
      : items

  return [sidebarItems, activeItemIndex, isParentItemActive ? parentItemFilter : activeItemFilter]
}
